function GRAPH-SEARCH(problem):
  frontier <- {node(problem.initial)}
  explored <- empty set
  loop:
    if frontier is empty: return failure
    node <- remove a node chosen by the strategy
    if problem.goal_test(node.state): return solution(node)
    add node.state to explored
    for each action in problem.actions(node.state):
      child <- child_node(problem, node, action)
      if child.state not in explored and not in frontier:
        add child to frontier

function MAX-VALUE(s, alpha, beta):
  if TERMINAL(s): return UTILITY(s)
  v <- -infinity
  for a in ACTIONS(s):
    v <- max(v, MIN-VALUE(RESULT(s,a), alpha, beta))
    if v >= beta: return v          # prune remaining children
    alpha <- max(alpha, v)
  return v
# MIN-VALUE is symmetric: v <- +infinity, take min,
# prune if v <= alpha, update beta <- min(beta, v)
